draw:
var g = 9.8;
var th = p.angle * Math.PI / 180;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var baseY = H * 0.78;
var apexX = W * 0.82;
var leftX = W * 0.16;
var run = apexX - leftX;
var rise = run * Math.tan(th);
if (rise > H * 0.42) { rise = H * 0.42; run = rise / Math.tan(th); apexX = leftX + run; }

// the bank: a wedge rising away from the centre of the circle
ctx.strokeStyle = C.rule;
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.moveTo(leftX, baseY);
ctx.lineTo(apexX, baseY);
ctx.lineTo(apexX, baseY - rise);
ctx.closePath();
ctx.fill();
ctx.stroke();

// centre-of-circle marker on the left
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(leftX - 10, baseY - rise - 30); ctx.lineTo(leftX - 10, baseY + 12); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("axis of the circle", 6, baseY + 26);

// car on the slope
var fx = leftX + run * 0.55, fy = baseY - (fx - leftX) * Math.tan(th);
var ux = Math.cos(th), uy = -Math.sin(th);      // up the slope
var nx = Math.sin(th), ny = -Math.cos(th);      // normal to the slope
ctx.save();
ctx.translate(fx, fy);
ctx.rotate(-th);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(-17, -13, 34, 13, 3); ctx.fill();
ctx.restore();
var cx = fx + nx * 7, cy = fy + ny * 7;

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 8 * Math.cos(a - 0.4), y1 - 8 * Math.sin(a - 0.4));
  ctx.lineTo(x1 - 8 * Math.cos(a + 0.4), y1 - 8 * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

var Nlen = H * 0.34;
var Nx = cx + nx * Nlen, Ny = cy + ny * Nlen;
arrow(cx, cy, Nx, Ny, C.accent);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("N", Nx + 5, Ny - 2);

// components of N: vertical N cos(th) and horizontal N sin(th)
ctx.strokeStyle = C.accent;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(Nx, Ny); ctx.lineTo(Nx, cy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(Nx, cy); ctx.lineTo(cx, cy); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("N cos" + String.fromCharCode(952) + "  (holds the weight up)", Nx + 5, (Ny + cy) / 2);
ctx.textAlign = "center";
ctx.fillText("N sin" + String.fromCharCode(952) + " = m v" + String.fromCharCode(178) + " / r", (Nx + cx) / 2, cy - 8);

// weight
var Wlen = Nlen * Math.cos(th);
arrow(cx, cy, cx, cy + Wlen, C.figure);
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("mg", cx + 6, cy + Wlen - 4);

// horizontal acceleration arrow, at the base
ctx.strokeStyle = C.ink;
arrow(fx, baseY + 22, fx - 52, baseY + 22, C.ink);
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("a = v" + String.fromCharCode(178) + "/r  (horizontal, toward the axis)", fx + 6, baseY + 26);

// angle arc at the foot of the wedge
ctx.strokeStyle = C.ink;
ctx.beginPath(); ctx.arc(apexX, baseY, 34, Math.PI - th, Math.PI); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText(String.fromCharCode(952) + " = " + p.angle.toFixed(0) + String.fromCharCode(176), apexX - 40, baseY - 6);

ctx.textAlign = "left";
out.note = "Only N and mg act. N tilts by " + p.angle.toFixed(0) + String.fromCharCode(176) + ", so it splits into a vertical part mg and an inward part m v" + String.fromCharCode(178) + "/r.";

var g = 9.8;
var th = p.angle * Math.PI / 180;
var tn = Math.tan(th);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var vdes = Math.sqrt(p.radius * g * tn);
var denMax = 1 - p.mu * tn;
var vmax = denMax <= 0.001 ? 1e9 : Math.sqrt(p.radius * g * (tn + p.mu) / denMax);
var numMin = tn - p.mu;
var vmin = numMin <= 0 ? 0 : Math.sqrt(p.radius * g * numMin / (1 + p.mu * tn));

var slip = 0;
if (p.speed > vmax) slip = 1;
else if (p.speed < vmin) slip = -1;

// cross-section of the bank
var baseY = H * 0.60;
var leftX = W * 0.10, apexX = W * 0.70;
var run = apexX - leftX;
var rise = run * tn;
if (rise > H * 0.34) { rise = H * 0.34; run = tn > 0 ? rise / tn : run; apexX = leftX + run; }
ctx.strokeStyle = C.rule;
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.moveTo(leftX, baseY); ctx.lineTo(apexX, baseY); ctx.lineTo(apexX, baseY - rise);
ctx.closePath(); ctx.fill(); ctx.stroke();

var drift = slip === 0 ? 0 : slip * 22 * (0.5 + 0.5 * Math.sin(t * 2.4));
var frac = 0.55 + drift / (run + 1);
if (frac > 0.95) frac = 0.95;
if (frac < 0.10) frac = 0.10;
var fx = leftX + run * frac;
var fy = baseY - (fx - leftX) * tn;

ctx.save();
ctx.translate(fx, fy);
ctx.rotate(-th);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(-18, -14, 36, 14, 3); ctx.fill();
ctx.fillStyle = C.paper;
ctx.beginPath(); ctx.roundRect(-9, -12, 12, 7, 2); ctx.fill();
ctx.restore();

// friction arrow along the surface, drawn only when friction is doing work
var ux = Math.cos(th), uy = -Math.sin(th);
var need = p.speed * p.speed / p.radius;
var fsign = (need * Math.cos(th) > g * Math.sin(th)) ? -1 : 1;  // +1 = up the slope
var flen = 34;
var ax0 = fx, ay0 = fy + 3;
ctx.strokeStyle = C.accent; ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.moveTo(ax0, ay0);
ctx.lineTo(ax0 + ux * flen * fsign, ay0 + uy * flen * fsign);
ctx.stroke();
var aa = Math.atan2(uy * fsign, ux * fsign);
var tipx = ax0 + ux * flen * fsign, tipy = ay0 + uy * flen * fsign;
ctx.beginPath();
ctx.moveTo(tipx, tipy);
ctx.lineTo(tipx - 7 * Math.cos(aa - 0.4), tipy - 7 * Math.sin(aa - 0.4));
ctx.lineTo(tipx - 7 * Math.cos(aa + 0.4), tipy - 7 * Math.sin(aa + 0.4));
ctx.closePath(); ctx.fill();
ctx.fillStyle = C.accent;
ctx.textAlign = fsign > 0 ? "left" : "right";
ctx.fillText("friction", tipx + 6 * fsign, tipy + 14);

ctx.textAlign = "left";
ctx.fillStyle = C.ink;
ctx.fillText(String.fromCharCode(952) + " = " + p.angle.toFixed(0) + String.fromCharCode(176) + ",  r = " + p.radius.toFixed(0) + " m,  " + String.fromCharCode(956) + " = " + p.mu.toFixed(2), leftX, H * 0.12);
if (slip > 0) ctx.fillText("too fast: sliding up and off the bank", leftX, H * 0.12 + 16);
else if (slip < 0) ctx.fillText("too slow: sliding down toward the axis", leftX, H * 0.12 + 16);
else ctx.fillText("holds the curve", leftX, H * 0.12 + 16);

// speed number line with the safe band shaded
var gy = H * 0.86, gx0 = W * 0.08, gx1 = W * 0.92;
var vTop = 60;
function sx(v) { var q = v / vTop; if (q > 1) q = 1; return gx0 + (gx1 - gx0) * q; }
ctx.fillStyle = C.faint;
ctx.fillRect(sx(vmin), gy - 12, sx(vmax > vTop ? vTop : vmax) - sx(vmin), 24);
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(gx1, gy); ctx.stroke();
ctx.strokeStyle = C.figure;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(sx(vdes), gy - 14); ctx.lineTo(sx(vdes), gy + 14); ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath(); ctx.moveTo(sx(p.speed), gy - 16); ctx.lineTo(sx(p.speed), gy + 16); ctx.stroke();
ctx.lineWidth = 1.5;
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("safe band of speeds (m/s)", (gx0 + gx1) / 2, gy - 20);
ctx.textAlign = "left";
ctx.fillText("0", gx0 - 3, gy + 26);
ctx.textAlign = "right";
ctx.fillText(vTop + " m/s", gx1, gy + 26);
ctx.textAlign = "center";
ctx.fillStyle = C.figure;
ctx.fillText("design", sx(vdes), gy + 26);

ctx.textAlign = "left";
var maxTxt = vmax > 1e8 ? "no upper limit" : vmax.toFixed(1) + " m/s";
out.note = "design speed " + vdes.toFixed(1) + " m/s   |   safe from " + vmin.toFixed(1) + " m/s to " + maxTxt + "   |   you are at " + p.speed.toFixed(1) + " m/s";

var g = 9.8;
var th = p.angle * Math.PI / 180;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var L = p.length;
var r = L * Math.sin(th);
var h = L * Math.cos(th);
var omega = Math.sqrt(g / h);
var v = omega * r;
var per = 2 * Math.PI / omega;
var tension = p.mass * g / Math.cos(th);

var pxPerM = (H * 0.62) / 2.5;
var px = W * 0.5, py = H * 0.14;
var rx = r * pxPerM, ry = rx * 0.30, cyc = py + h * pxPerM;

// pivot
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px, py, 4, 0, 6.2832); ctx.fill();
ctx.fillRect(px - 26, py - 8, 52, 5);

// vertical axis
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, cyc + ry + 14); ctx.stroke();
ctx.setLineDash([]);

// the circle the ball traces, drawn in perspective
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.ellipse(px, cyc, rx, ry, 0, 0, 6.2832); ctx.stroke();

// cone edges
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px - rx, cyc); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px + rx, cyc); ctx.stroke();

// ball
var ph = omega * t;
var bx = px + rx * Math.cos(ph), by = cyc + ry * Math.sin(ph);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(bx, by); ctx.stroke();
ctx.lineWidth = 1.5;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(bx, by, 8, 0, 6.2832); ctx.fill();

// labels
ctx.fillStyle = C.accent;
ctx.textAlign = "right";
ctx.fillText("L = " + L.toFixed(2) + " m", (px + bx) / 2 - 8, (py + by) / 2);
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("h = L cos" + String.fromCharCode(952) + " = " + h.toFixed(2) + " m", px + 6, py + h * pxPerM * 0.5);
ctx.textAlign = "center";
ctx.fillText("r = L sin" + String.fromCharCode(952) + " = " + r.toFixed(2) + " m", px + rx * 0.5, cyc + ry + 28);
ctx.strokeStyle = C.ink;
ctx.beginPath(); ctx.moveTo(px, cyc); ctx.lineTo(px + rx, cyc); ctx.stroke();

// angle arc at the pivot
ctx.strokeStyle = C.ink;
ctx.beginPath(); ctx.arc(px, py, 30, Math.PI / 2 - th, Math.PI / 2); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText(String.fromCharCode(952) + " = " + p.angle.toFixed(0) + String.fromCharCode(176), px + 6, py + 44);

// force triangle in the corner
var ox = W * 0.12, oy = H * 0.30, sc = 46;
ctx.strokeStyle = C.figure; ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox, oy + sc); ctx.stroke();
ctx.fillText("mg", ox - 22, oy + sc * 0.6);
ctx.strokeStyle = C.accent; ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.moveTo(ox, oy + sc); ctx.lineTo(ox + sc * Math.tan(th), oy + sc); ctx.stroke();
ctx.fillText("T sin" + String.fromCharCode(952), ox + 4, oy + sc + 14);
ctx.strokeStyle = C.ink;
ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox + sc * Math.tan(th), oy + sc); ctx.stroke();

out.note = "v = " + v.toFixed(2) + " m/s   |   period = " + per.toFixed(2) + " s   |   tension = " + tension.toFixed(2) + " N   |   " + String.fromCharCode(969) + " = " + omega.toFixed(2) + " rad/s";
